  <div id="c2" style="${STY('var(--acc)')}top:700px;">MAX EFFICIENCY<br><span style="font-size:32px;font-weight:600;opacity:0.9;margin-top:8px;">TENSOR LIBRARY</span></div>
  <div id="ft" style="position:absolute;top:960px;width:100%;text-align:center;color:#ffffff;font-size:32px;font-weight:800;opacity:0;font-family:inherit;text-transform:uppercase;letter-spacing:1px;">GGML • 15,898 STARS • C++ • MIT</div>
`;

const cards = [0, 1, 2].map(i => root.querySelector('#c' + i));
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});
const foot = root.querySelector('#ft');

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Cards Entrance
  const delays = [0.1, 1.2, 2.3];
  cards.forEach((el, i) => {
    const s = spr(tf, delays[i], 0.8, 8);
    el.style.opacity = clamp(s * 2);
    const scale = lerp(0.8, 1, E_OUT(clamp(s)));
    const slide = lerp(50, 0, E_OUT(clamp(s)));
    el.style.transform = `translateY(${slide}px) scale(${scale})`;
  });

  // Connector Lines
  const lineDelays = [0.9, 2.0];
  lines.forEach((l, i) => {
    const lp = clamp((tf - lineDelays[i]) * 2.5);
    l.el.style.strokeDashoffset = l.len * (1 - E_OUT(lp));
  });

  // Footer Text
  const fs = spr(tf, 2.8, 0.9, 7);
  foot.style.opacity = clamp(fs);
  foot.style.transform = `translateY(${lerp(20, 0, E_OUT(clamp(fs)))}px)`;
}
